sort(A)
def kSum(A, target, k, start):
  if k == 2:                      # two-pointer base case
    lo, hi = start, len(A)-1
    while lo < hi:
      s = A[lo] + A[hi]
      if s < target: lo += 1
      elif s > target: hi -= 1
      else:
        emit(A[lo], A[hi]); lo += 1; hi -= 1
        while lo<hi and A[lo]==A[lo-1]: lo += 1   # dedup
  else:
    for i in range(start, len(A)-k+1):
      if i>start and A[i]==A[i-1]: continue       # dedup
      kSum(A, target-A[i], k-1, i+1)              # fix one, recurse

