dp.pseudo:
solve(s, k):
  n = len(s)
  dp = n x n grid of 0      # dp[i][j] = min deletions on s[i..j]
  for length in 2..n:
    for i in 0..n-length:
      j = i + length - 1
      if s[i] == s[j]:
        dp[i][j] = dp[i+1][j-1]
      else:
        dp[i][j] = 1 + min(dp[i+1][j], dp[i][j-1])
  return dp[0][n-1] <= k
  # equivalently: return (n - LPS(s)) <= k

