bfs.pseudo:
BFS(begin, end, dict):
  if end not in dict: return NONE
  frontier = {begin}; visited = {begin}; level = 1
  while frontier:
     next = {}; usedThisLevel = {}
     for w in frontier:
        for i in 0..len(w):
           for c in 'a'..'z':
              nb = w[:i] + c + w[i+1:]
              if nb in dict and nb not in visited:
                 next.add(nb); usedThisLevel.add(nb)
                 parents[nb].append(w)   # only for #126 path reconstruct
        if w == end: return level / backtrack(parents)
     visited |= usedThisLevel            # batch-mark AFTER level (#126)
     frontier = next; level += 1
  return NONE

