// #2402 canonical two-heap engine
sort meetings by start
available = min-heap of room ids [0..n-1]
busy      = min-heap of (endTime, roomId)
for (s, e) in meetings:
    while busy and busy.top.endTime <= s:        // free finished rooms
        push busy.pop().roomId into available
    if available:
        r = available.pop()
        push (e, r) into busy                    // on time
    else:
